const sampleQuestionIds = new Set(['APT-143','GS-284','RSN-091','GS-307','APT-162','RSN-114','GS-331','APT-180','RSN-137']);
const storedQuestions = JSON.parse(localStorage.getItem('exam-prep-questions') || localStorage.getItem('prepledger-questions') || '[]');
let questions = storedQuestions.filter(question => !sampleQuestionIds.has(question.id));
let nav = 'Dashboard', bankFilter = 'All', bankSearch = '', sortOrder = 'newest';
let exam = null, timerId = null;
let firebaseAuth = null, authUser = null, authIssue = '', authLoading = true, authMode = 'signin';
const todayLabel = new Intl.DateTimeFormat(undefined, { weekday: 'long', month: 'long', day: 'numeric' }).format(new Date());
const icon = {Dashboard:'⌂','Question Bank':'▤','Create Question':'+','Import Questions':'⇧','Daily Mock':'▧','Weekly Mock':'◴','Weekly Rough Notes':'✎','Book Collection':'▥','Mistakes':'!','Analytics':'◔','Settings':'⚙'};
const routes = ['Dashboard','Question Bank','Create Question','Import Questions','Daily Mock','Weekly Mock','Weekly Rough Notes','Book Collection','Mistakes','Analytics','Settings'];
function save(){localStorage.setItem('exam-prep-questions',JSON.stringify(questions))}
function getWeeklyNotes(){try{return JSON.parse(localStorage.getItem('exam-prep-weekly-rough-pages')||'[]')}catch{return []}}
function saveWeeklyNotes(pages){localStorage.setItem('exam-prep-weekly-rough-pages',JSON.stringify(pages))}
function prepareRoughPages(testQuestions=[]){const saved=new Map(getWeeklyNotes().map(page=>[page.questionId,page]));const pages=testQuestions.map((question,index)=>saved.get(question.id)||({questionId:question.id,questionNumber:index+1,questionText:question.text,imageData:''}));saveWeeklyNotes(pages);return pages}
function blankCanvas(context,canvas){context.fillStyle='#ffffff';context.fillRect(0,0,canvas.width,canvas.height);context.strokeStyle='#d9e5e0';context.lineWidth=2;for(let y=110;y<canvas.height;y+=72){context.beginPath();context.moveTo(50,y);context.lineTo(canvas.width-50,y);context.stroke()}context.strokeStyle='#e9b4b4';context.beginPath();context.moveTo(140,40);context.lineTo(140,canvas.height-40);context.stroke()}
function mountRoughCanvas(canvas,page,onSave){const context=canvas.getContext('2d');blankCanvas(context,canvas);if(page.imageData){const image=new Image();image.onload=()=>context.drawImage(image,0,0,canvas.width,canvas.height);image.src=page.imageData}let drawing=false,last=null;const position=event=>{const bounds=canvas.getBoundingClientRect();return {x:(event.clientX-bounds.left)*canvas.width/bounds.width,y:(event.clientY-bounds.top)*canvas.height/bounds.height}};const save=()=>{page.imageData=canvas.toDataURL('image/jpeg',.72);onSave()};canvas.onpointerdown=event=>{drawing=true;last=position(event);canvas.setPointerCapture(event.pointerId)};canvas.onpointermove=event=>{if(!drawing)return;const next=position(event);context.strokeStyle='#163230';context.lineWidth=7;context.lineCap='round';context.beginPath();context.moveTo(last.x,last.y);context.lineTo(next.x,next.y);context.stroke();last=next};canvas.onpointerup=()=>{if(drawing){drawing=false;save()}};canvas.onpointercancel=()=>{if(drawing){drawing=false;save()}}}
function roughPdfBlob(pages){if(!window.jspdf?.jsPDF)throw new Error('PDF tools are still loading. Please try again.');const document=new window.jspdf.jsPDF({unit:'pt',format:'a4',compress:true});pages.forEach((page,index)=>{if(index)document.addPage();document.setFont('helvetica','bold');document.setFontSize(15);document.text('Exam Prep - Weekly Rough Work',40,45);document.setFont('helvetica','normal');document.setFontSize(10);document.text(`Question ${page.questionNumber}`,40,67);const questionLines=document.splitTextToSize(page.questionText||'Blank rough-work page',515);document.text(questionLines,40,84);const top=Math.min(160,100+questionLines.length*14);if(page.imageData){document.addImage(page.imageData,'JPEG',40,top,515,644)}else{document.setDrawColor(215,229,224);for(let y=top+24;y<790;y+=24)document.line(40,y,555,y)}});return document.output('blob')}
function downloadBlob(blob,fileName){const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=fileName;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(link.href),1000)}
async function uploadRoughWorkPdf(){const pages=getWeeklyNotes();if(!pages.length){toast('Open a weekly mock to create rough-work pages.');return}try{const blob=roughPdfBlob(pages);const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(blob)});const response=await fetch('/api/upload-rough-work',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({fileName:`weekly-rough-work-${Date.now()}.pdf`,pdfBase64:base64})});const body=await response.json();if(!response.ok)throw new Error(body.error||'Unable to save the PDF to S3.');toast('Rough-work PDF saved to S3.');return body}catch(error){toast(error.message||'Unable to save the PDF to S3.')}}
function pdfSafe(value=''){return String(value).replace(/[^\x20-\x7E]/g,' ').replace(/[\\()]/g,'\\$&')}
function wrapPdfText(value,max=88){const words=pdfSafe(value).split(/\s+/),lines=[];let line='';words.forEach(word=>{if((line+' '+word).trim().length>max&&line){lines.push(line);line=word}else line=(line+' '+word).trim()});if(line)lines.push(line);return lines}
function makePdf(title,lines){const pageLines=lines.reduce((pages,line)=>{let current=pages[pages.length-1];if(current.length>=44){current=[];pages.push(current)}current.push(line);return pages},[[]]);const pageIds=pageLines.map((_,index)=>5+index*2);const objects=['<< /Type /Catalog /Pages 2 0 R >>',`<< /Type /Pages /Kids [${pageIds.map(id=>`${id} 0 R`).join(' ')}] /Count ${pageIds.length} >>`,'<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>'];pageLines.forEach((page,index)=>{const content=`BT /F1 10 Tf 45 800 Td (${pdfSafe(title)}) Tj 0 -22 Td /F1 8 Tf ${page.map((line,i)=>`${i?'0 -15 Td ':''}(${pdfSafe(line)}) Tj`).join(' ')} ET`;const contentId=4+index*2;objects.push(`<< /Length ${content.length} >>\nstream\n${content}\nendstream`);objects.push(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 842] /Resources << /Font << /F1 3 0 R >> >> /Contents ${contentId} 0 R >>`)});let pdf='%PDF-1.4\n',offsets=[0];objects.forEach((object,index)=>{offsets.push(pdf.length);pdf+=`${index+1} 0 obj\n${object}\nendobj\n`});const xref=pdf.length;pdf+=`xref\n0 ${objects.length+1}\n0000000000 65535 f \n${offsets.slice(1).map(offset=>String(offset).padStart(10,'0')+' 00000 n \n').join('')}trailer\n<< /Size ${objects.length+1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`;return new Blob([pdf],{type:'application/pdf'})}
function downloadPdf(filename,title,lines){const link=document.createElement('a');link.href=URL.createObjectURL(makePdf(title,lines));link.download=filename;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(link.href),1000)}
function paperLines(title,paper,includeAnswers=false){const lines=[title,'APPSC Group 1 | Generated from your Exam Prep question bank',''];paper.forEach((question,index)=>{lines.push(...wrapPdfText(`${index+1}. ${question.text}`));question.options.forEach((option,optionIndex)=>lines.push(...wrapPdfText(`   ${'ABCD'[optionIndex]}. ${option}`)));if(includeAnswers){lines.push(`   Answer: ${'ABCD'[question.answer]}. ${question.options[question.answer]}`);if(question.explanation)lines.push(...wrapPdfText(`   Explanation: ${question.explanation}`))}lines.push('')});return lines}
function toast(message){const e=document.querySelector('.toast') || document.body.appendChild(Object.assign(document.createElement('div'),{className:'toast'}));e.textContent=message;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2800)}
function loginPage(){const signUp=authMode==='signup';document.querySelector('#app').innerHTML=`<main class="auth-shell"><section class="auth-card"><div class="brand auth-brand"><span class="brand-mark">E</span> Exam Prep</div><div class="eyebrow">PERSONAL EXAM WORKSPACE</div><h1>${signUp?'Create your account':'Sign in to continue'}</h1><p class="subtle">${signUp?'Create an email and password for your private Exam Prep workspace.':'Use your Exam Prep email and password.'}</p>${authIssue?`<div class="auth-message">${escapeHtml(authIssue)}</div>`:''}<form id="loginForm" class="auth-form"><label>Email address<input class="input" name="email" type="email" autocomplete="email" required placeholder="you@example.com"></label><label>Password<input class="input" name="password" type="password" autocomplete="${signUp?'new-password':'current-password'}" minlength="6" required placeholder="At least 6 characters"></label>${signUp?'<label>Confirm password<input class="input" name="confirmPassword" type="password" autocomplete="new-password" minlength="6" required placeholder="Re-enter your password"></label>':''}${signUp?'':'<button class="text-link auth-forgot" type="button" id="forgotPassword">Forgot password?</button>'}<button class="button" type="submit" ${firebaseAuth?'':'disabled'}>${firebaseAuth?(signUp?'Create account':'Sign in'):'Authentication unavailable'}</button></form><button class="text-link auth-switch" type="button" id="switchAuth">${signUp?'Already have an account? Sign in':'New here? Create an account'}</button><p class="auth-foot">Your study data remains private to your browser until a shared backend is configured.</p></section></main>`;document.querySelector('#loginForm').onsubmit=async event=>{event.preventDefault();if(!firebaseAuth)return;const form=new FormData(event.currentTarget),email=form.get('email'),password=form.get('password');if(signUp&&password!==form.get('confirmPassword')){authIssue='Passwords do not match.';loginPage();return}try{if(signUp)await firebaseAuth.signUp(email,password);else await firebaseAuth.signIn(email,password)}catch(error){authIssue=error.message.replace('Firebase: ','');loginPage()}};document.querySelector('#switchAuth').onclick=()=>{authMode=signUp?'signin':'signup';authIssue='';loginPage()};document.querySelector('#forgotPassword')?.addEventListener('click',async()=>{const email=document.querySelector('[name="email"]').value.trim();if(!email){authIssue='Enter your email address first, then select Forgot password.';loginPage();return}if(!firebaseAuth)return;try{await firebaseAuth.reset(email);authIssue='Password reset email sent. Check your inbox.';loginPage()}catch(error){authIssue=error.message.replace('Firebase: ','');loginPage()}})}
async function initializeAuthentication(){try{const response=await fetch('/api/auth-config');if(!response.ok)throw new Error('Firebase Authentication is not configured yet. Add the Firebase values in Vercel, then redeploy.');const firebaseConfig=await response.json();const [{initializeApp},{getAuth,onAuthStateChanged,createUserWithEmailAndPassword,signInWithEmailAndPassword,sendPasswordResetEmail,signOut}]=await Promise.all([import('https://www.gstatic.com/firebasejs/10.12.2/firebase-app.js'),import('https://www.gstatic.com/firebasejs/10.12.2/firebase-auth.js')]);const auth=getAuth(initializeApp(firebaseConfig));firebaseAuth={signIn:(email,password)=>signInWithEmailAndPassword(auth,email,password),signUp:(email,password)=>createUserWithEmailAndPassword(auth,email,password),reset:email=>sendPasswordResetEmail(auth,email),signOut:()=>signOut(auth)};onAuthStateChanged(auth,user=>{authLoading=false;authUser=user;render()})}catch(error){authLoading=false;authIssue=error.message;render()}}
function layout(content,title=nav){document.querySelector('#app').innerHTML=`<div class="shell"><aside class="sidebar" id="sidebar"><div class="brand"><span class="brand-mark">E</span> Exam Prep</div><div class="profile"><small>PERSONAL EXAM PLAN</small><strong>APPSC Group 1</strong></div><div class="nav-label">WORKSPACE</div><nav class="nav">${routes.map(x=>`<button class="${nav===x?'active':''}" data-nav="${x}"><span class="icon">${icon[x]}</span>${x}</button>`).join('')}</nav><div class="sidebar-footer">Question bank first.<br/>Practice made fresh.</div></aside><main class="main"><header class="topbar"><div class="top-actions"><button class="icon-button mobile-menu" id="menuBtn" aria-label="Open navigation">☰</button><div class="crumb">Personal workspace / <strong>${title}</strong></div></div><div class="top-actions"><button class="icon-button" id="quickAdd" aria-label="Create question">+</button><button class="button secondary sign-out" id="signOut">Sign out</button></div></header>${content}</main></div>`; bindGlobal()}
function bindGlobal(){document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{nav=b.dataset.nav;render()});document.querySelector('#menuBtn')?.addEventListener('click',()=>document.querySelector('#sidebar').classList.toggle('open'));document.querySelector('#quickAdd').onclick=()=>{nav='Create Question';render()};document.querySelector('#signOut').onclick=()=>firebaseAuth?.signOut()}
function heading(title,desc,action=''){return `<div class="page-heading"><div><div class="eyebrow">APPSC Group 1 · Personal plan</div><h1>${title}</h1><p class="subtle">${desc}</p></div>${action}</div>`}
function dashboard(){const attempted=questions.filter(question=>question.attempts>0);const accuracy=attempted.length?Math.round(attempted.reduce((total,question)=>total+(question.attempts-question.wrong)/question.attempts,0)/attempted.length*100):'—';layout(`<section class="page">${heading('Today’s preparation','Start by adding a question or importing a reviewed CSV.','<button class="button" id="dailyFromHero">▧ Generate daily mock</button>')}<div class="hero"><div class="hero-copy"><div class="eyebrow" style="color:#f2c878">LOCAL QUESTION BANK</div><h2>Build the bank. Sharpen the attempt.</h2><p>Add your own material, then turn it into fresh practice papers.</p><button class="button" id="captureBtn">+ Capture a question</button></div></div><div class="stats"><div class="stat"><div class="stat-head"><span>QUESTION BANK</span><span>▤</span></div><strong>${questions.length.toLocaleString()}</strong><span class="trend">Your saved questions</span></div><div class="stat"><div class="stat-head"><span>AVERAGE ACCURACY</span><span>◔</span></div><strong>${accuracy}</strong><span class="trend">${attempted.length?'From your attempts':'No attempts yet'}</span></div><div class="stat"><div class="stat-head"><span>DAILY MOCKS</span><span>▧</span></div><strong>0</strong><span class="trend">No papers generated yet</span></div><div class="stat"><div class="stat-head"><span>WEEKLY MOCK</span><span>◴</span></div><strong>Not started</strong><span class="trend">Add questions to begin</span></div></div><div class="grid-2"><section class="panel"><div class="panel-title"><div><h2>This week's study cycle</h2><p class="subtle">Use this as a quiet guide for daily practice and the weekly mock.</p></div><button class="text-link" data-goto="Weekly Mock">Set up mock</button></div><div class="week">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map((day,index)=>`<div class="day ${index===5?'today':''} ${index===6?'locked':''}"><strong>${day}</strong><span>${index===5?'Today':index===6?'Mock':'Pending'}</span></div>`).join('')}</div><div style="margin-top:25px"><div class="panel-title"><div><h2>Today's capture target</h2><p class="subtle">Set targets after you decide what to study today.</p></div></div>${progressRows()}</div></section><section class="panel"><div class="panel-title"><div><h2>Recent activity</h2><p class="subtle">Your real preparation activity will appear here.</p></div></div><div class="empty">No activity yet. Add a question to start your bank.</div></section></div></section>`);document.querySelector('#captureBtn').onclick=document.querySelector('#quickAdd').onclick;document.querySelector('#dailyFromHero').onclick=()=>{nav='Daily Mock';render()};bindGoto()}
function progressRows(){return [['GS',0,0,''],['Aptitude',0,0,'amber'],['Reasoning',0,0,'blue']].map(([subject,added,target,color])=>`<div class="subject-row"><strong>${subject}</strong><div class="progress ${color}"><span style="width:0"></span></div><span class="muted">${added}/${target}</span></div>`).join('')}
function bank(){let list=questions.filter(q=>(bankFilter==='All'||q.subject===bankFilter)&&(`${q.text} ${q.topic} ${q.source}`.toLowerCase().includes(bankSearch.toLowerCase())));if(sortOrder==='wrong')list.sort((a,b)=>b.wrong-a.wrong);if(sortOrder==='attempts')list.sort((a,b)=>b.attempts-a.attempts);layout(`<section class="page">${heading('Question bank','Every stored question is reusable material for a fresh practice paper.','<button class="button" id="newQuestion">+ Create question</button>')}<div class="toolbar"><input id="bankSearch" class="input search" placeholder="Search question, topic, or source" value="${bankSearch}"><div class="filters"><select id="subjectFilter"><option>All</option><option>GS</option><option>Aptitude</option><option>Reasoning</option></select><select id="sortFilter"><option value="newest">Newest added</option><option value="attempts">Most attempted</option><option value="wrong">Most wrong</option></select></div></div><div class="table-wrap"><table class="question-table"><thead><tr><th>Question</th><th>Subject / topic</th><th>Difficulty</th><th>Source</th><th>Attempts</th><th>Accuracy</th></tr></thead><tbody>${list.length?list.map(q=>`<tr data-question="${q.id}"><td><div class="question-text">${q.text}</div><small class="muted">${q.id}</small></td><td><span class="tag">${q.subject}</span><div class="muted" style="margin-top:6px">${q.topic}</div></td><td><span class="tag ${q.difficulty==='Hard'?'red':q.difficulty==='Medium'?'amber':''}">${q.difficulty}</span></td><td>${q.source}<div class="muted">p. ${q.page}</div></td><td>${q.attempts}</td><td>${q.attempts?Math.round((q.attempts-q.wrong)/q.attempts*100):'—'}%</td></tr>`).join(''):`<tr><td colspan="6" class="empty">No questions match these filters.</td></tr>`}</tbody></table></div></section>`);document.querySelector('#subjectFilter').value=bankFilter;document.querySelector('#sortFilter').value=sortOrder;document.querySelector('#bankSearch').oninput=e=>{bankSearch=e.target.value;bank()};document.querySelector('#subjectFilter').onchange=e=>{bankFilter=e.target.value;bank()};document.querySelector('#sortFilter').onchange=e=>{sortOrder=e.target.value;bank()};document.querySelector('#newQuestion').onclick=()=>{nav='Create Question';render()};document.querySelectorAll('[data-question]').forEach(r=>r.onclick=()=>showQuestion(r.dataset.question))}
function showQuestion(id){const q=questions.find(x=>x.id===id);document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="questionModal"><div class="modal"><div class="eyebrow">${q.id} · ${q.subject} / ${q.topic}</div><h2 style="font-size:18px;line-height:1.4;margin-top:8px">${q.text}</h2>${q.options.map((o,i)=>`<p style="margin:8px 0">${'ABCD'[i]}. ${o}</p>`).join('')}<div class="notice" style="margin-top:16px"><strong>Answer: ${'ABCD'[q.answer]}</strong><br>${q.explanation}</div><div class="modal-actions"><button class="button secondary" id="closeQuestion">Close</button></div></div></div>`);document.querySelector('#closeQuestion').onclick=()=>document.querySelector('#questionModal').remove()}
function createQuestion(){layout(`<section class="page">${heading('Create question','Capture a question manually, with complete metadata for better future mocks.')}<div class="panel" style="max-width:960px"><div class="notice">Questions are saved to this device in the MVP. The schema is designed to map cleanly to a future Firestore collection.</div><form id="questionForm" class="form-grid"><div class="field full"><label>Question text</label><textarea required class="input" name="text" placeholder="Write the full multiple-choice question"></textarea></div><div class="field"><label>Option A</label><input required class="input" name="a"></div><div class="field"><label>Option B</label><input required class="input" name="b"></div><div class="field"><label>Option C</label><input required class="input" name="c"></div><div class="field"><label>Option D</label><input required class="input" name="d"></div><div class="field"><label>Correct answer</label><select class="input" name="answer"><option value="0">Option A</option><option value="1">Option B</option><option value="2">Option C</option><option value="3">Option D</option></select></div><div class="field"><label>Difficulty</label><select class="input" name="difficulty"><option>Easy</option><option selected>Medium</option><option>Hard</option></select></div><div class="field"><label>Subject</label><select class="input" name="subject"><option>GS</option><option>Aptitude</option><option>Reasoning</option></select></div><div class="field"><label>Topic</label><input required class="input" name="topic" placeholder="e.g. Percentage"></div><div class="field"><label>Source / book</label><input class="input" name="source" placeholder="e.g. APPSC Notes"></div><div class="field"><label>Page number</label><input class="input" type="number" name="page" min="1" placeholder="e.g. 143"></div><div class="field full"><label>Explanation</label><textarea class="input" name="explanation" placeholder="Why is this the correct answer?"></textarea></div><div class="field full" style="display:flex;align-items:center;justify-content:flex-end"><button class="button" type="submit">Save to question bank</button></div></form></div></section>`);document.querySelector('#questionForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target), subject=f.get('subject');questions.unshift({id:`${subject==='Aptitude'?'APT':subject==='Reasoning'?'RSN':'GS'}-${String(Math.floor(Math.random()*900)+100)}`,subject,topic:f.get('topic'),difficulty:f.get('difficulty'),source:f.get('source')||'Personal notes',page:f.get('page')||'—',attempts:0,wrong:0,text:f.get('text'),options:['a','b','c','d'].map(x=>f.get(x)),answer:Number(f.get('answer')),explanation:f.get('explanation')||'Explanation to be added.'});save();nav='Question Bank';toast('Question saved to your bank.');render()}}
function escapeHtml(value=''){return String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[char]))}
function parseCsv(text){const rows=[],row=[];let cell='',quoted=false;for(let i=0;i<text.length;i++){const char=text[i];if(char==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(char===','&&!quoted){row.push(cell.trim());cell=''}else if((char==='\n'||char==='\r')&&!quoted){if(char==='\r'&&text[i+1]==='\n')i++;row.push(cell.trim());if(row.some(Boolean))rows.push(row.splice(0));cell=''}else cell+=char}row.push(cell.trim());if(row.some(Boolean))rows.push(row);return rows}
function csvDrafts(text){const [header,...rows]=parseCsv(text);if(!header)return[];const keys=header.map(value=>value.toLowerCase().replace(/[^a-z0-9]/g,''));const find=(row,...names)=>{const index=keys.findIndex(key=>names.includes(key));return index<0?'':row[index]||''};return rows.map(row=>{const options=['a','b','c','d'].map(letter=>find(row,`option${letter}`,letter));const answerRaw=find(row,'correctanswer','answer','correctoption');const answerLetter=answerRaw.trim().replace(/^option\s*/i,'').charAt(0).toUpperCase();return {text:find(row,'question','questiontext','text'),options,answer:['A','B','C','D'].indexOf(answerLetter)>=0?['A','B','C','D'].indexOf(answerLetter):Math.max(0,options.findIndex(option=>option===answerRaw)),subject:find(row,'subject')||'GS',topic:find(row,'topic')||'Unsorted',difficulty:find(row,'difficulty')||'Medium',source:find(row,'source','book','bookname')||'CSV import',page:find(row,'page','pagenumber')||'—',explanation:find(row,'explanation','solution')||''}}).filter(draft=>draft.text&&draft.options.every(Boolean))}
function csvReview(fileName,drafts){const result=document.querySelector('#importResult');if(!drafts.length){result.innerHTML='<div class="notice" style="margin-top:18px">No complete questions were found. Use columns: <strong>Question, Option A, Option B, Option C, Option D, Correct Answer, Subject, Topic, Difficulty, Source, Page, Explanation</strong>.</div>';return}result.innerHTML=`<div class="notice" style="margin-top:18px"><strong>${escapeHtml(fileName)}</strong> contains ${drafts.length} complete question${drafts.length===1?'':'s'}. Review the drafts below before saving them.</div><div class="table-wrap" style="margin-top:14px"><table class="question-table"><thead><tr><th>Question draft</th><th>Subject</th><th>Topic</th><th>Answer</th></tr></thead><tbody>${drafts.map((draft,index)=>`<tr><td><input class="input csv-text" data-index="${index}" value="${escapeHtml(draft.text)}"><small class="muted">${escapeHtml(draft.options.map((option,i)=>`${'ABCD'[i]}. ${option}`).join(' · '))}</small></td><td><input class="input csv-subject" data-index="${index}" value="${escapeHtml(draft.subject)}"></td><td><input class="input csv-topic" data-index="${index}" value="${escapeHtml(draft.topic)}"></td><td>${'ABCD'[draft.answer]}</td></tr>`).join('')}</tbody></table></div><button class="button" id="saveCsvDrafts" style="margin-top:16px">Save ${drafts.length} reviewed question${drafts.length===1?'':'s'}</button>`;document.querySelector('#saveCsvDrafts').onclick=()=>{drafts.forEach((draft,index)=>{draft.text=document.querySelector(`.csv-text[data-index="${index}"]`).value.trim();draft.subject=document.querySelector(`.csv-subject[data-index="${index}"]`).value.trim()||'GS';draft.topic=document.querySelector(`.csv-topic[data-index="${index}"]`).value.trim()||'Unsorted'});const approved=drafts.filter(draft=>draft.text);questions.unshift(...approved.map(draft=>({id:`${draft.subject==='Aptitude'?'APT':draft.subject==='Reasoning'?'RSN':'GS'}-${String(Math.floor(Math.random()*900)+100)}`,...draft,attempts:0,wrong:0})));save();toast(`${approved.length} reviewed question${approved.length===1?'':'s'} saved.`);nav='Question Bank';render()}}
function importer(){layout(`<section class="page">${heading('Import questions','Review every extracted or uploaded item before it earns a place in your question bank.','<a class="button secondary" href="assets/exam-prep-sample-questions.csv" download>↓ Download sample CSV</a>')}<div class="steps"><span class="on">1. Upload</span><span>2. Extract</span><span>3. Review</span><span>4. Save</span></div><div class="panel" style="max-width:850px"><div class="import-zone"><div style="font-size:28px">⇧</div><strong>Drop notes, book pages, PDF, or CSV here</strong><p class="subtle">CSV uploads are ready now. Image and PDF intake is ready for an OCR connection in Phase 5.</p><label class="button secondary" style="margin-top:10px">Choose a file<input id="uploadInput" type="file" accept="image/*,.pdf,.csv,text/csv"></label></div><p class="subtle" style="margin:16px 0 0">CSV columns: Question, Option A, Option B, Option C, Option D, Correct Answer, Subject, Topic, Difficulty, Source, Page, Explanation.</p><div id="importResult"></div></div></section>`);document.querySelector('#uploadInput').onchange=e=>{const file=e.target.files[0];if(!file)return;if(file.name.toLowerCase().endsWith('.csv')){const reader=new FileReader();reader.onload=()=>csvReview(file.name,csvDrafts(reader.result));reader.readAsText(file);return}document.querySelector('#importResult').innerHTML=`<div class="notice" style="margin-top:18px"><strong>${escapeHtml(file.name)}</strong> is ready for review. In this MVP, the extraction review is demonstrated with a structured preview while a future OCR provider can populate these fields.</div><div class="panel" style="margin-top:14px"><div class="eyebrow">Extracted draft · review required</div><h3 style="font-size:16px;margin-top:8px">Which Article establishes the Finance Commission?</h3><p class="subtle">A. 280 &nbsp; B. 324 &nbsp; C. 356 &nbsp; D. 368</p><button class="button" id="reviewExtract" style="margin-top:12px">Review and edit draft</button></div>`;document.querySelector('#reviewExtract').onclick=()=>{nav='Create Question';render();toast('Extraction draft opened for review.')}}}
function daily(){let paper=[];const refreshPaper=()=>{const total=[...document.querySelectorAll('.mockCount')].reduce((sum,input)=>sum+Number(input.value),0),time=document.querySelector('#mockTime').value;paper=shuffle([...questions]).slice(0,Math.min(total,questions.length));document.querySelector('#mockSheet').innerHTML=paper.length?paperMarkup(paper,paper.length,time):'<div class="empty">Add questions to your bank before generating a daily quiz.</div>'};layout(`<section class="page">${heading('Daily mock','Create a fresh quiz from your own question bank.')}<div class="mock-layout"><section class="panel"><h2>Quiz configuration</h2><p class="subtle">Questions are selected without duplicates.</p><div class="config-row"><strong>GS</strong><input class="input mockCount" type="number" min="0" value="20"></div><div class="config-row"><strong>Aptitude</strong><input class="input mockCount" type="number" min="0" value="10"></div><div class="config-row"><strong>Reasoning</strong><input class="input mockCount" type="number" min="0" value="10"></div><div class="field" style="margin-top:18px"><label>Suggested time (minutes)</label><input id="mockTime" class="input" type="number" value="75"></div><button class="button" id="generatePaper" style="width:100%;justify-content:center;margin-top:18px" ${questions.length?'':'disabled'}>↻ Generate daily quiz</button><button class="button secondary" id="downloadDaily" style="width:100%;justify-content:center;margin-top:10px" ${questions.length?'':'disabled'}>↓ Generate quiz PDF</button><button class="button secondary" id="downloadDailyKey" style="width:100%;justify-content:center;margin-top:10px" ${questions.length?'':'disabled'}>↓ Generate answer key PDF</button></section><section class="mock-sheet" id="mockSheet"><div class="empty">${questions.length?'Generate a daily quiz to preview it here.':'Add questions to your bank before generating a daily quiz.'}</div></section></div></section>`);document.querySelector('#generatePaper').onclick=()=>{refreshPaper();toast('Fresh daily quiz generated.');};document.querySelector('#downloadDaily').onclick=()=>{if(!paper.length)refreshPaper();if(!paper.length)return;downloadPdf('exam-prep-daily-quiz.pdf','Exam Prep - Daily Quiz',paperLines('DAILY QUIZ',paper));toast('Daily quiz PDF downloaded.');};document.querySelector('#downloadDailyKey').onclick=()=>{if(!paper.length)refreshPaper();if(!paper.length)return;downloadPdf('exam-prep-daily-answer-key.pdf','Exam Prep - Daily Answer Key',paperLines('DAILY QUIZ - ANSWER KEY',paper,true));toast('Daily answer key PDF downloaded.');}}
function paperMarkup(list,total,time){return `<div class="sheet-header"><div class="eyebrow">Personal Competitive Exam Practice</div><h2>Daily Mock Test</h2><div class="sheet-meta"><span>Prepared ${todayLabel}</span><span>${total} questions</span><span>${time} minutes</span></div></div><p class="subtle" style="font-size:12px">Instructions: Select the most appropriate answer. Answers and detailed solutions are generated separately after you complete the paper.</p>${list.map((q,i)=>`<div class="sheet-question"><strong>${i+1}.</strong>${q.text}<div class="sheet-options">${q.options.map((o,j)=>`<span>${'ABCD'[j]}. ${o}</span>`).join('')}</div></div>`).join('')}`}
function shuffle(a){return a.sort(()=>Math.random()-.5)}
function weekly(){let pdfPaper=[];const weeklyPaper=()=>{if(!pdfPaper.length)pdfPaper=shuffle([...questions]).slice(0,Math.min(questions.length,100));return pdfPaper};layout(`<section class="page">${heading('Weekly mock','A distraction-free, computer-based exam simulation for your Sunday attempt.',`<button class="button" id="startMock" ${questions.length?'':'disabled'}>${questions.length?'Start weekly mock →':'Add questions to begin'}</button>`)}<div class="grid-2"><section class="panel"><div class="eyebrow">EXAM SETUP</div><h2 style="font-family:Fraunces,serif;font-size:25px;margin-top:6px">Weekly full-length mock</h2><p class="subtle">The default paper follows your APPSC Group 1 plan. Configure the live test before you begin.</p><div class="config-row"><strong>GS</strong><span>50 questions</span></div><div class="config-row"><strong>Aptitude</strong><span>25 questions</span></div><div class="config-row"><strong>Reasoning</strong><span>25 questions</span></div><div class="config-row"><strong>Duration</strong><span>120 minutes</span></div><button class="button secondary" id="downloadWeekly" style="width:100%;justify-content:center;margin-top:18px" ${questions.length?'':'disabled'}>↓ Generate weekly quiz PDF</button><button class="button secondary" id="downloadWeeklyKey" style="width:100%;justify-content:center;margin-top:10px" ${questions.length?'':'disabled'}>↓ Generate weekly answer key PDF</button></section><section class="panel"><h2>Exam conditions</h2><div class="activity"><div class="activity-item"><i class="activity-dot"></i><div><strong>Timer begins when you enter</strong><small>Auto-submit at zero. Your answers save as you work.</small></div></div><div class="activity-item"><i class="activity-dot" style="background:#e4a447"></i><div><strong>Question palette</strong><small>Track answered, unanswered and marked-for-review questions.</small></div></div><div class="activity-item"><i class="activity-dot" style="background:#2e6fc4"></i><div><strong>Result analysis</strong><small>See subject and topic performance after submission.</small></div></div></div></section></div></section>`);document.querySelector('#startMock').onclick=startExam;document.querySelector('#downloadWeekly').onclick=()=>{const paper=weeklyPaper();if(!paper.length)return;downloadPdf('exam-prep-weekly-quiz.pdf','Exam Prep - Weekly Quiz',paperLines('WEEKLY QUIZ',paper));toast('Weekly quiz PDF downloaded.');};document.querySelector('#downloadWeeklyKey').onclick=()=>{const paper=weeklyPaper();if(!paper.length)return;downloadPdf('exam-prep-weekly-answer-key.pdf','Exam Prep - Weekly Answer Key',paperLines('WEEKLY QUIZ - ANSWER KEY',paper,true));toast('Weekly answer key PDF downloaded.');}}
function startExam(){if(!questions.length){toast('Add questions to your bank before starting a mock.');return}exam={questions:shuffle([...questions]).slice(0,Math.min(questions.length,20)),idx:0,answers:{},review:new Set(),seconds:120*60};renderExam();timerId=setInterval(()=>{exam.seconds--;const t=document.querySelector('#timer');if(t)t.textContent=formatTime(exam.seconds);if(exam.seconds<=0){clearInterval(timerId);confirmSubmit(true)}},1000)}
function formatTime(s){return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
function roughNotebookMarkup(pages,index=0,modal=false){const page=pages[index]||{questionNumber:1,questionText:'Blank rough-work page',imageData:''};return `<section class="${modal?'rough-note-sheet':'rough-note-page'}"><div class="rough-note-head"><div><div class="eyebrow">WEEKLY MOCK ROUGH WORK</div><h2>Question ${page.questionNumber} of ${pages.length}</h2></div>${modal?'<button class="icon-button" id="closeExamNotes" aria-label="Close rough notes">×</button>':'<span class="muted">Saved locally</span>'}</div><p class="rough-question">${escapeHtml(page.questionText)}</p><div class="rough-canvas-wrap"><canvas id="roughCanvas" class="rough-canvas" width="1440" height="1800"></canvas></div><div class="rough-note-foot"><button class="button secondary" id="previousRoughPage" ${index===0?'disabled':''}>← Previous</button><span>Page ${index+1} / ${pages.length}</span><div><button class="button secondary" id="clearRoughPage">Clear page</button><button class="button secondary" id="nextRoughPage" ${index===pages.length-1?'disabled':''}>Next →</button></div></div></section>`}
function bindRoughNotebook(root,pages,index,close){const save=()=>saveWeeklyNotes(pages);mountRoughCanvas(root.querySelector('#roughCanvas'),pages[index],save);root.querySelector('#previousRoughPage').onclick=()=>renderRoughNotebook(root,pages,index-1,close);root.querySelector('#nextRoughPage').onclick=()=>renderRoughNotebook(root,pages,index+1,close);root.querySelector('#clearRoughPage').onclick=()=>{pages[index].imageData='';save();renderRoughNotebook(root,pages,index,close)}}
function renderRoughNotebook(root,pages,index,close){root.innerHTML=roughNotebookMarkup(pages,index,Boolean(close));if(close)root.querySelector('#closeExamNotes').onclick=close;bindRoughNotebook(root,pages,index,close)}
function openExamNotes(){const pages=prepareRoughPages(exam.questions);document.body.insertAdjacentHTML('beforeend','<div class="modal-backdrop" id="roughNotesModal"><div id="roughNotebookModal"></div></div>');const modal=document.querySelector('#roughNotesModal');renderRoughNotebook(document.querySelector('#roughNotebookModal'),pages,exam.idx,()=>modal.remove())}
function renderExam(){const q=exam.questions[exam.idx], answered=Object.keys(exam.answers).length;document.querySelector('#app').innerHTML=`<div class="exam-shell"><header class="exam-top"><div class="exam-title">APPSC Group 1 <small>· Weekly mock</small></div><div class="exam-top-actions"><button class="exam-note-button" id="openExamNotes" aria-label="Open rough notes" title="Rough notes">✎</button><div>Time remaining <span class="timer" id="timer">${formatTime(exam.seconds)}</span></div><button class="button warn" id="submitExam">Submit test</button></div></header><div class="exam-main"><main class="exam-content"><div class="exam-section"><span>${q.subject.toUpperCase()} · ${q.topic}</span><span>Question ${exam.idx+1} of ${exam.questions.length}</span></div><section class="exam-card"><div class="exam-q">${q.text}</div><div class="answer-options">${q.options.map((o,i)=>`<button class="answer ${exam.answers[exam.idx]===i?'selected':''}" data-answer="${i}"><span class="answer-letter">${'ABCD'[i]}</span><span>${o}</span></button>`).join('')}</div><div class="exam-controls"><div><button class="button secondary" id="prev" ${exam.idx===0?'disabled':''}>← Previous</button><button class="button secondary" id="clear" ${exam.answers[exam.idx]===undefined?'disabled':''}>Clear response</button></div><div><button class="button secondary" id="mark">${exam.review.has(exam.idx)?'Remove review':'Mark for review'}</button><button class="button" id="next">${exam.idx===exam.questions.length-1?'Review test':'Save & next'} →</button></div></div></section></main><aside class="exam-aside"><h3>Question palette</h3><div class="palette">${exam.questions.map((x,i)=>`<button class="pal ${i===exam.idx?'current':''} ${exam.review.has(i)?'review':exam.answers[i]!==undefined?'answered':''}" data-pal="${i}">${i+1}</button>`).join('')}</div><div class="legend"><span><i class="a"></i>Answered (${answered})</span><span><i class="r"></i>Marked for review (${exam.review.size})</span><span><i></i>Unanswered (${exam.questions.length-answered})</span></div><button class="button warn" id="asideSubmit" style="width:100%;justify-content:center;margin-top:22px">Submit test</button></aside></div></div>`;document.querySelector('#openExamNotes').onclick=openExamNotes;document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{exam.answers[exam.idx]=Number(b.dataset.answer);renderExam()});document.querySelectorAll('[data-pal]').forEach(b=>b.onclick=()=>{exam.idx=Number(b.dataset.pal);renderExam()});document.querySelector('#prev').onclick=()=>{exam.idx--;renderExam()};document.querySelector('#next').onclick=()=>{if(exam.idx<exam.questions.length-1){exam.idx++;renderExam()}else confirmSubmit(false)};document.querySelector('#clear').onclick=()=>{delete exam.answers[exam.idx];renderExam()};document.querySelector('#mark').onclick=()=>{exam.review.has(exam.idx)?exam.review.delete(exam.idx):exam.review.add(exam.idx);renderExam()};document.querySelector('#submitExam').onclick=()=>confirmSubmit(false);document.querySelector('#asideSubmit').onclick=()=>confirmSubmit(false)}
function confirmSubmit(auto){const answered=Object.keys(exam.answers).length,unanswered=exam.questions.length-answered;document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop"><div class="modal"><div class="eyebrow">${auto?'Time is up':'Review your attempt'}</div><h2>${auto?'Your test will now be submitted.':'Submit weekly mock?'}</h2><p class="subtle">${auto?'The timer reached zero.':'You can still revisit unanswered questions before submitting.'}</p><div class="summary-grid"><div><strong>${answered}</strong><span>Answered</span></div><div><strong>${unanswered}</strong><span>Unanswered</span></div><div><strong>${exam.review.size}</strong><span>For review</span></div></div><div class="modal-actions">${auto?'': '<button class="button secondary" id="continueExam">Continue</button>'}<button class="button warn" id="finalSubmit">Submit now</button></div></div></div>`);document.querySelector('#continueExam')?.addEventListener('click',()=>document.querySelector('.modal-backdrop').remove());document.querySelector('#finalSubmit').onclick=finishExam}
function finishExam(){clearInterval(timerId);let correct=0,wrong=0;exam.questions.forEach((q,i)=>{if(exam.answers[i]===q.answer)correct++;else if(exam.answers[i]!==undefined)wrong++});nav='Analytics';renderResults({correct,wrong,unattempted:exam.questions.length-correct-wrong,total:exam.questions.length})}
function renderResults(r){const accuracy=r.correct+r.wrong?Math.round(r.correct/(r.correct+r.wrong)*100):0;const sections=[...new Set(exam.questions.map(question=>question.subject))].map(subject=>{const entries=exam.questions.map((question,index)=>({question,index})).filter(entry=>entry.question.subject===subject);const attempted=entries.filter(entry=>exam.answers[entry.index]!==undefined);const correct=attempted.filter(entry=>exam.answers[entry.index]===entry.question.answer).length;return {subject,correct,attempted:attempted.length,total:entries.length,accuracy:attempted.length?Math.round(correct/attempted.length*100):0}});document.querySelector('#app').innerHTML=`<div class="results page"><div class="page-heading"><div><div class="eyebrow">WEEKLY MOCK · RESULTS</div><h1>Your attempt, mapped clearly.</h1><p class="subtle">Use this analysis to decide what earns revision time next.</p></div><button class="button secondary" id="backDashboard">Back to dashboard</button></div><div class="score-band"><div><div class="score-number">${r.correct}/${r.total}</div><p>Score · ${accuracy}% accuracy</p></div><div><strong>${r.correct} correct</strong><p>${r.wrong} wrong · ${r.unattempted} unattempted</p></div><div><strong>${formatTime(120*60-exam.seconds)} taken</strong><p>Results from this attempt</p></div></div><div class="result-grid"><section class="panel"><h2>Section performance</h2>${sections.map(section=>`<div class="metric-row"><div><strong>${section.subject}</strong><small class="muted"> ${section.correct} correct of ${section.total}</small></div><div class="progress"><span style="width:${section.accuracy}%"></span></div><strong>${section.accuracy}%</strong></div>`).join('')}</section><section class="panel"><h2>Revision priorities</h2><div class="notice"><strong>Review this attempt before your next mock.</strong><br>Incorrect responses are the best starting point for your next revision set.</div><div class="activity-item"><i class="activity-dot" style="background:#e4a447"></i><div><strong>${r.wrong} incorrect response${r.wrong===1?'':'s'}</strong><small>These can be reviewed in My Mistakes.</small></div></div><button class="button" id="mistakeTest" style="margin-top:18px">Open mistake bank</button></section></div></div>`;document.querySelector('#backDashboard').onclick=()=>{nav='Dashboard';render()};document.querySelector('#mistakeTest').onclick=()=>{nav='Mistakes';render()}}
function mistakes(){const bad=questions.filter(question=>question.wrong>0);const table=bad.length?`<div class="table-wrap"><table class="question-table"><thead><tr><th>Question</th><th>Topic</th><th>Wrong attempts</th><th>Next action</th></tr></thead><tbody>${bad.map(question=>`<tr data-question="${question.id}"><td><div class="question-text">${question.text}</div></td><td>${question.topic}</td><td><span class="tag red">${question.wrong} wrong</span></td><td><button class="text-link">Review explanation</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="panel"><div class="empty">No mistakes recorded yet. Completed mock attempts will add incorrect answers here.</div></div>';layout(`<section class="page">${heading('My mistakes','Questions that deserve another honest attempt, kept separate from the noise.','<button class="button" id="mistakeMock">Generate mistake test</button>')}<div class="stats"><div class="stat"><div class="stat-head"><span>WRONG QUESTIONS</span><span>!</span></div><strong>${bad.length}</strong><span class="trend">${bad.length?'Ready for revision':'No mistakes yet'}</span></div><div class="stat"><div class="stat-head"><span>REPEATED ERRORS</span><span>↻</span></div><strong>${bad.filter(question=>question.wrong>2).length}</strong><span class="trend">Needs focused practice</span></div><div class="stat"><div class="stat-head"><span>NEVER SEEN</span><span>◦</span></div><strong>${questions.filter(question=>!question.attempts).length}</strong><span class="trend">Fresh material</span></div><div class="stat"><div class="stat-head"><span>REVIEW QUEUE</span><span>⌁</span></div><strong>0</strong><span class="trend">No items queued</span></div></div>${table}</section>`);document.querySelector('#mistakeMock').onclick=()=>{nav='Daily Mock';render();toast('Add questions first, then configure a mistake-only paper.')}}
function analytics(){const attempted=questions.filter(question=>question.attempts>0);const topics=[...new Set(attempted.map(question=>question.topic))];layout(`<section class="page">${heading('Preparation analytics','An honest view of what is improving and what needs attention.')}<div class="grid-2"><section class="panel"><h2>Topic accuracy</h2>${topics.length?topics.map(topic=>{const entries=attempted.filter(question=>question.topic===topic);const accuracy=Math.round(entries.reduce((total,question)=>total+(question.attempts-question.wrong)/question.attempts,0)/entries.length*100);return `<div class="metric-row"><strong>${topic}</strong><div class="progress"><span style="width:${accuracy}%"></span></div><strong>${accuracy}%</strong></div>`}).join(''):'<div class="empty">No attempt data yet. Analytics will appear after you complete a mock.</div>'}</section><section class="panel"><h2>What to do next</h2><div class="notice"><strong>Build your first real dataset.</strong><br>Add questions, generate a mock, and complete an attempt to unlock personal recommendations.</div><button class="button" id="newRevision">Create revision test</button></section></div></section>`);document.querySelector('#newRevision').onclick=()=>{nav='Daily Mock';render();toast('Add questions before creating a revision paper.')}}
function weeklyRoughNotes(){const pages=getWeeklyNotes();layout(`<section class="page">${heading('Weekly rough notes','Your saved question-by-question working from the latest weekly mock.',pages.length?'<div class="top-actions"><button class="button secondary" id="downloadRoughPdf">↓ Download PDF</button><button class="button" id="uploadRoughPdf">↑ Save PDF to S3</button></div>':'')}<div id="roughNotebookPage">${pages.length?roughNotebookMarkup(pages):'<section class="panel"><div class="empty">Start a weekly mock and open the notes icon to create your rough-work booklet.</div></section>'}</div></section>`);if(!pages.length)return;bindRoughNotebook(document.querySelector('#roughNotebookPage'),pages,0);document.querySelector('#downloadRoughPdf').onclick=()=>{try{downloadBlob(roughPdfBlob(getWeeklyNotes()),`exam-prep-weekly-rough-work-${Date.now()}.pdf`);toast('Rough-work PDF downloaded.')}catch(error){toast(error.message)}};document.querySelector('#uploadRoughPdf').onclick=uploadRoughWorkPdf}
function bookCollection(){const books=[...new Set(questions.map(question=>question.source).filter(source=>source&&source!=='Personal notes'&&source!=='CSV import'))].map(source=>({source,items:questions.filter(question=>question.source===source)}));layout(`<section class="page">${heading('Book collection','A source-aware view of the books and notes behind your question bank.','<button class="button" id="addFromBook">+ Add a question</button>')}${books.length?`<div class="table-wrap"><table class="question-table"><thead><tr><th>Book / source</th><th>Questions saved</th><th>Subjects</th><th>Pages captured</th></tr></thead><tbody>${books.map(book=>`<tr><td><div class="question-text">${escapeHtml(book.source)}</div></td><td>${book.items.length}</td><td>${[...new Set(book.items.map(question=>question.subject))].join(', ')}</td><td>${book.items.map(question=>question.page).filter(page=>page&&page!=='—').join(', ')||'—'}</td></tr>`).join('')}</tbody></table></div>`:'<div class="panel"><div class="empty">No books or notes have been recorded yet. Add questions with a source or import a CSV with a Source column to build your collection.</div></div>'}</section>`);document.querySelector('#addFromBook').onclick=()=>{nav='Create Question';render()}}
function settings(){layout(`<section class="page">${heading('Settings','Your personal plan, structured for a calmer weekly rhythm.')}<div class="panel" style="max-width:700px"><div class="form-grid"><div class="field"><label>Target examination</label><select class="input"><option>APPSC Group 1</option><option>APPSC Group 2</option><option>IBPS PO</option></select></div><div class="field"><label>Weekly mock day</label><select class="input"><option>Sunday</option><option>Saturday</option></select></div><div class="field"><label>Weekly duration (minutes)</label><input class="input" type="number" value="120"></div><div class="field"><label>Accuracy revision threshold</label><input class="input" type="number" value="70"></div></div><button class="button" id="saveSettings" style="margin-top:20px">Save preferences</button></div></section>`);document.querySelector('#saveSettings').onclick=()=>toast('Preferences saved locally.')}
function bindGoto(){document.querySelectorAll('[data-goto]').forEach(b=>b.onclick=()=>{nav=b.dataset.goto;render()})}
function render(){if(authLoading){document.querySelector('#app').innerHTML='<main class="auth-shell"><div class="auth-loading">Loading Exam Prep...</div></main>';return}if(!authUser){loginPage();return}if(nav==='Dashboard')dashboard();else if(nav==='Question Bank')bank();else if(nav==='Create Question')createQuestion();else if(nav==='Import Questions')importer();else if(nav==='Daily Mock')daily();else if(nav==='Weekly Mock')weekly();else if(nav==='Weekly Rough Notes')weeklyRoughNotes();else if(nav==='Book Collection')bookCollection();else if(nav==='Mistakes')mistakes();else if(nav==='Analytics')analytics();else settings()}
initializeAuthentication();
